import { Link } from "react-router-dom";
import Teachersidebar from "./Teachersidebar";
import { useState, useEffect } from "react";
import { Routes as Switch, Route } from 'react-router-dom';
import axios from "axios";

function Addcourse() {
    const [cats, setCats] = useState([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    
    const [courseData, setCourseData] = useState({
        "category": '',
        "title": '',
        "description": '',
        "featured_image": null,
        "techs": ''
    });

    useEffect(() => {
        try {
            axios.get("http://127.0.0.1:8000/api/category/").then((response) => {
                setCats(response.data);
                console.log(response.data);
            }).catch(error => {
                console.log(error);
                setError('Failed to load categories');
            });
        } catch (error) {
            console.log(error);
        }
    }, []);

    const handleChange = (event) => {
        setCourseData({
            ...courseData,
            [event.target.name]: event.target.value
        });
    }

    const handleFileChange = (event) => {
        setCourseData({
            ...courseData,
            [event.target.name]: event.target.files[0]
        });
    }

    const submitForm = (event) => {
        event.preventDefault();
        setIsLoading(true);
        setError('');
        setSuccess('');

        const courseFormData = new FormData();
        
        // Fixed: Using correct variable name - courseFormData instead of formData
        courseFormData.append("category", courseData.category);
        courseFormData.append("title", courseData.title);
        courseFormData.append("description", courseData.description);
        
        // Only append image if file was selected
        if (courseData.featured_image) {
            courseFormData.append("featured_image", courseData.featured_image, courseData.featured_image.name);
        }
        
        courseFormData.append("techs", courseData.techs);

        try {
            // Fixed: Correct API URL - removed extra colon
            axios.post("http://127.0.0.1:8000/api/course/", courseFormData, {
                headers: {
                    'content-type': 'multipart/form-data'
                }
            }).then((response) => {
                setSuccess('Course added successfully!');
                // Reset form
                setCourseData({
                    "category": '',
                    "title": '',
                    "description": '',
                    "featured_image": null,
                    "techs": ''
                });
                // Redirect after success
                setTimeout(() => {
                    window.location.href = "/teacher-mycourses";
                }, 2000);
            }).catch(error => {
                console.log(error);
                setError('Failed to add course. Please try again.');
            });
        } catch (error) {
            console.log(error);
            setError('An unexpected error occurred.');
        } finally {
            setIsLoading(false);
        }
    }

    return (
        <div className="container mt-4">
            <div className="row">
                <aside className="col-md-3">
                    <Teachersidebar />
                </aside>
                <section className="col-md-9">
                    <div className="card">
                        <h5 className="card-header">Add Course</h5>
                        <div className="card-body">
                            {/* Success and Error Messages */}
                            {success && (
                                <div className="alert alert-success">{success}</div>
                            )}
                            {error && (
                                <div className="alert alert-danger">{error}</div>
                            )}
                            
                            {/* Fixed: onSubmit on form instead of onClick on button */}
                            <form onSubmit={submitForm}>
                                <div className="mb-3">
                                    <label htmlFor="category" className="form-label">Category</label>
                                    <select 
                                        name="category" 
                                        onChange={handleChange} 
                                        value={courseData.category}
                                        className="form-control"
                                        required
                                    >
                                        <option value="">Select Category</option>
                                        {cats.map((category, index) =>
                                            <option key={index} value={category.id}>{category.title}</option>
                                        )}
                                    </select>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="title" className="form-label">Title</label>
                                    <input 
                                        type="text" 
                                        name="title" 
                                        onChange={handleChange} 
                                        value={courseData.title}
                                        className="form-control" 
                                        id="title"
                                        required
                                    />
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="description" className="form-label">Description</label>
                                    {/* Fixed: Added name and onChange for description */}
                                    <textarea 
                                        className="form-control" 
                                        name="description"
                                        onChange={handleChange}
                                        value={courseData.description}
                                        rows="4"
                                    />
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="featured_image" className="form-label">Featured Image</label>
                                    {/* Fixed: Changed name from "featured_img" to "featured_image" to match state */}
                                    <input 
                                        type="file" 
                                        id="featured_image" 
                                        onChange={handleFileChange} 
                                        name="featured_image" 
                                        className="form-control"
                                        accept="image/*"
                                    />
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="techs" className="form-label">Technologies used</label>
                                    <textarea 
                                        className="form-control" 
                                        onChange={handleChange} 
                                        name="techs"
                                        value={courseData.techs}
                                        rows="3"
                                        placeholder="Comma-separated technologies (e.g., React, Python, Django)"
                                    />
                                </div>
                                <button 
                                    type="submit" 
                                    className="btn btn-primary"
                                    disabled={isLoading}
                                >
                                    {isLoading ? 'Adding Course...' : 'Submit'}
                                </button>
                            </form>
                        </div>
                    </div>
                </section>
            </div>
        </div>
    );
}

export default Addcourse;
